using System;
using System.Linq;
using Nexo.Core.Domain.Bricks;
using Nexo.Core.Domain.Execution;

namespace Nexo.Samples.Dogfood.Colours;

public sealed class RgbHexParseBrick : DomainBrick
{
    public RgbHexParseBrick()
    {
        Id = "rgb-hex-parse";
        Name = "RGB Hex Parse";
        Description = "Parses a 6-digit hexadecimal RGB colour into its channels and a normalized form.";
        Interface = new BrickInterface
        {
            Inputs = [new BrickInputDefinition("hex", "string", "colour text")],
            Outputs =
            [
                new BrickOutputDefinition("isValid", "bool", "valid"),
                new BrickOutputDefinition("red", "int", "red"),
                new BrickOutputDefinition("green", "int", "green"),
                new BrickOutputDefinition("blue", "int", "blue"),
                new BrickOutputDefinition("normalized", "string", "normalized")
            ]
        };
    }

    public override Task<BrickOutput> ExecuteAsync(
        BrickInput input,
        ImplementationType implementation,
        IExecutionContext context,
        CancellationToken cancellationToken = default)
    {
        var hex = input.Get<string>("hex", string.Empty) ?? string.Empty;

        bool isValid = false;
        int red = 0;
        int green = 0;
        int blue = 0;
        string normalized = string.Empty;

        string digits = null;

        if (hex.Length == 6)
        {
            digits = hex;
        }
        else if (hex.Length == 7 && hex[0] == '#')
        {
            digits = hex.Substring(1);
        }

        if (digits != null)
        {
            bool allHex = true;
            for (int i = 0; i < digits.Length; i++)
            {
                char c = digits[i];
                bool isHex = (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
                if (!isHex)
                {
                    allHex = false;
                    break;
                }
            }

            if (allHex)
            {
                isValid = true;
                red = Convert.ToInt32(digits.Substring(0, 2), 16);
                green = Convert.ToInt32(digits.Substring(2, 2), 16);
                blue = Convert.ToInt32(digits.Substring(4, 2), 16);
                normalized = "#" + digits.ToLowerInvariant();
            }
        }

        var output = new BrickOutput();
        output.Set("isValid", isValid);
        output.Set("red", red);
        output.Set("green", green);
        output.Set("blue", blue);
        output.Set("normalized", normalized);

        return Task.FromResult(output);
    }
}
